CREATE TEMP TABLE oct21_changed ON COMMIT DROP AS SELECT p.id FROM oct21_plan p JOIN public.fixtures f USING(id)
 WHERE row(f.home_team_id,f.away_team_id) IS DISTINCT FROM row(p.home_team_id,p.away_team_id);
DO $$ BEGIN
 IF (SELECT count(*) FROM oct21_plan)<>8 OR (SELECT count(*) FROM oct21_changed)<>3 OR (SELECT count(*) FROM public.fixtures WHERE competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND round_number=2)<>8 THEN RAISE EXCEPTION 'Unexpected round size or changed fixtures'; END IF;
 IF EXISTS(SELECT 1 FROM oct21_plan p LEFT JOIN public.fixtures f USING(id) WHERE f.id IS NULL OR to_jsonb(f) IS DISTINCT FROM to_jsonb(jsonb_populate_record(null::public.fixtures,p.original)) OR f.competition_season_id<>'be008d39-f175-45c1-a232-2148d84b1cf9' OR f.match_date<>'2026-10-21' OR f.round_number<>2 OR f.publication_state<>'published' OR f.schedule_status<>'scheduled') THEN RAISE EXCEPTION 'Round 2 fixture baseline changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions r JOIN oct21_plan p ON p.id=r.fixture_id) THEN RAISE EXCEPTION 'Result already exists; stop'; END IF;
 IF (SELECT count(DISTINCT team_id) FROM (SELECT home_team_id team_id FROM oct21_plan UNION ALL SELECT away_team_id FROM oct21_plan)t)<>16 OR (SELECT count(DISTINCT(kickoff_time,court)) FROM oct21_plan)<>8 THEN RAISE EXCEPTION 'Round participation or slot collision'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='be008d39-f175-45c1-a232-2148d84b1cf9' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Edition is no longer active'; END IF;
END $$;
CREATE TEMP TABLE oct21_protected ON COMMIT DROP AS
SELECT 'fixtures' kind,md5(coalesce(jsonb_agg(to_jsonb(f) ORDER BY id)::text,'[]')) hash FROM public.fixtures f WHERE NOT EXISTS(SELECT 1 FROM oct21_changed c WHERE c.id=f.id)
UNION ALL SELECT 'results',md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) FROM public.result_versions r
UNION ALL SELECT 'teams',md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'[]')) FROM public.teams t;
UPDATE public.fixtures f SET publication_state='draft' FROM oct21_changed c WHERE f.id=c.id;
UPDATE public.fixtures f SET home_team_id=p.home_team_id,away_team_id=p.away_team_id,publication_state='published'
 FROM oct21_plan p JOIN oct21_changed c USING(id) WHERE f.id=p.id;
INSERT INTO public.result_versions(fixture_id,revision,status,home_score,away_score)
 SELECT id,1,'published',home_score,away_score FROM oct21_plan;
DO $$ BEGIN
 IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(f) ORDER BY id)::text,'[]')) FROM public.fixtures f WHERE NOT EXISTS(SELECT 1 FROM oct21_changed c WHERE c.id=f.id)) IS DISTINCT FROM (SELECT hash FROM oct21_protected WHERE kind='fixtures') OR
 (SELECT md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) FROM public.result_versions r WHERE NOT EXISTS(SELECT 1 FROM oct21_plan p WHERE p.id=r.fixture_id)) IS DISTINCT FROM (SELECT hash FROM oct21_protected WHERE kind='results') OR
 (SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'[]')) FROM public.teams t) IS DISTINCT FROM (SELECT hash FROM oct21_protected WHERE kind='teams') THEN RAISE EXCEPTION 'Protected records changed'; END IF;
 IF (SELECT count(*) FROM public.result_versions r JOIN oct21_plan p ON p.id=r.fixture_id WHERE r.status='published' AND r.home_score=p.home_score AND r.away_score=p.away_score AND r.revision=1 AND r.published_at IS NOT NULL)<>8 THEN RAISE EXCEPTION 'Result verification failed'; END IF;
 IF EXISTS(SELECT 1 FROM oct21_plan p JOIN public.fixtures f USING(id) WHERE row(f.home_team_id,f.away_team_id,f.kickoff_time,f.court) IS DISTINCT FROM row(p.home_team_id,p.away_team_id,p.kickoff_time,p.court) OR f.publication_state<>'published' OR (to_jsonb(f)-'home_team_id'-'away_team_id'-'publication_state'-'schedule_version'-'updated_at') IS DISTINCT FROM (to_jsonb(jsonb_populate_record(null::public.fixtures,p.original))-'home_team_id'-'away_team_id'-'publication_state'-'schedule_version'-'updated_at')) THEN RAISE EXCEPTION 'Fixture verification failed'; END IF;
END $$;
COMMIT;
